input.content:
import sys
from build123d import import_step, Compound

path = sys.argv[1]
shape = import_step(path)
def bb(s):
    b = s.bounding_box()
    return f"min=({b.min.X:.2f},{b.min.Y:.2f},{b.min.Z:.2f}) max=({b.max.X:.2f},{b.max.Y:.2f},{b.max.Z:.2f}) size=({b.size.X:.2f},{b.size.Y:.2f},{b.size.Z:.2f})"
print("TOTAL", bb(shape))
def walk(s, depth=0, maxd=int(sys.argv[2]) if len(sys.argv) > 2 else 2):
    for c in getattr(s, "children", []) or []:
        print("  " * depth + f"- {c.label!r} {type(c).__name__} {bb(c)}")
        if depth + 1 < maxd:
            walk(c, depth + 1, maxd)
walk(shape)
if not shape.children:
    for i, so in enumerate(shape.solids()):
        print(f"solid {i}: {bb(so)} vol={so.volume:.1f}")

