import sys
from build123d import import_step, GeomType

path, *names = sys.argv[1:]
shape = import_step(path)
targets = []
def walk(s):
    for c in s.children or []:
        if any(n in (c.label or "") for n in names):
            targets.append(c)
        else:
            walk(c)
walk(shape)
if not targets:
    targets = [shape]
for t in targets:
    b = t.bounding_box()
    print(f"== {t.label} bbox min=({b.min.X:.2f},{b.min.Y:.2f},{b.min.Z:.2f}) max=({b.max.X:.2f},{b.max.Y:.2f},{b.max.Z:.2f})")
    seen = set()
    for f in t.faces():
        if f.geom_type == GeomType.CYLINDER:
            r = f.radius
            ax = f.axis_of_rotation if hasattr(f, "axis_of_rotation") else None
            fb = f.bounding_box()
            d = ax.direction
            o = fb.center()
            key = (round(r, 2), round(abs(d.X), 1), round(abs(d.Y), 1), round(abs(d.Z), 1), round(o.X, 1), round(o.Y, 1), round(o.Z, 1))
            if key in seen or r > 15:
                continue
            seen.add(key)
            print(f"  cyl r={r:.2f} dir=({d.X:.2f},{d.Y:.2f},{d.Z:.2f}) center=({o.X:.2f},{o.Y:.2f},{o.Z:.2f}) ext=({fb.size.X:.1f},{fb.size.Y:.1f},{fb.size.Z:.1f})")

